<template>
  <ProgressRoot
    v-bind="delegatedProps"
    :class="cn('relative h-4 w-full overflow-hidden rounded-full bg-accent border', props.class)"
  >
    <ProgressIndicator
      v-for="(segment, index) in reversedSegments"
      :key="index"
      :class="
        cn(
          'h-full flex-1 transition-all absolute rounded-full',
          props.indicatorClass,
          segment.color ? segment.color : 'bg-primary'
        )
      "
      :style="{
        width: index < segments.length - 1 ? `${segment.value}%` : `calc(${segment.value}% + 12px)`,
        left: `${segments.slice(0, segments.length - index - 1).reduce((acc, segment) => acc + segment.value, 0)}%`,
      }"
    />
  </ProgressRoot>
</template>

<script setup lang="ts">
import { cn } from '@/components/ui/utils';
import { ProgressIndicator, ProgressRoot, type ProgressRootProps } from 'reka-ui';
import { computed, type HTMLAttributes } from 'vue';
import type { ProgressSegments } from './index';

const props = withDefaults(
  defineProps<
    ProgressRootProps & {
      class?: HTMLAttributes['class'];
      indicatorClass?: HTMLAttributes['class'];
      segments: ProgressSegments[];
    }
  >(),
  {
    class: undefined,
    indicatorClass: undefined,
  }
);

const reversedSegments = computed(() => {
  return [...props.segments].reverse();
});

const delegatedProps = computed(() => {
  const { class: _, ...delegated } = props;

  return delegated;
});
</script>
